function asText(value) {
  if (typeof value === "string") return value.trim();
  if (value && typeof value === "object") {
    if (typeof value.output === "string") return value.output.trim();
    if (typeof value.text === "string") return value.text.trim();
    return JSON.stringify(value, null, 2);
  }
  return "";
}

function negationPreface(notes) {
  const sentences = String(notes || "").split(/(?<=[.!?])\s+/).filter(function (part) {
    return part.trim();
  });
  const lines = [
    "NEGATION CHECK FIRST. Do this before every owner check, deadline check, and fact-preservation check.",
    "The words deadline, owner, assigned, and stated are not evidence that a value exists. If no, none, nobody, not stated, not given, or not assigned negates them, that field is ABSENT.",
    "An ABSENT field written as Not stated / unclear is correct. It is not a reason for REVISE.",
  ];
  const seen = {};
  sentences.forEach(function (sentence) {
    const s = sentence.toLowerCase();
    const ownerNeg = /\b(nobody was assigned|no owner was named|no owner was stated|nobody was named as responsible|no one was assigned|not assigned)\b/.test(s);
    const deadlineNeg = /\b(no deadline was stated|no deadline was given|deadline was not stated|deadline was not given)\b/.test(s);
    const decisionNeg = /\b(no decision was made|no decision was stated)\b/.test(s);
    if (ownerNeg && !seen.owner) {
      seen.owner = true;
      lines.push("OWNER ABSENT. The notes say the owner was not assigned. Nobody was assigned is not an owner. Owner: Not stated / unclear is correct. Do not return REVISE for a missing owner.");
    }
    if (deadlineNeg && !seen.deadline) {
      seen.deadline = true;
      lines.push("DEADLINE ABSENT. The notes say no deadline was stated or given. That is not a deadline. The words deadline and stated are negated by no. Deadline: Not stated / unclear is correct. Do not say the draft is missing a deadline, and do not return REVISE for this field.");
    }
    if (decisionNeg && !seen.decision) {
      seen.decision = true;
      lines.push("DECISION ABSENT. No decision was made is not a decision. Do not return REVISE for a missing decision.");
    }
  });
  if (!seen.owner && !seen.deadline && !seen.decision) {
    lines.push("No explicit absence was found. Only a positive named value, such as Maya or Friday, must be preserved.");
  }
  return lines;
}

function reviewerMessage(originalNotes, draft) {
  const message = negationPreface(originalNotes).concat([
    "Compare this draft with the complete original meeting notes.",
    "Use the negation check above before State 1. A field marked ABSENT is not a fact that was removed.",
    "State 1 applies only to a field the negation check did not mark ABSENT. State 1, explicit value: the notes positively name one owner or one day, such as Maya and Friday, in a sentence that is not negated. The draft must keep that value. Replacing Maya or Friday with Not stated / unclear is REVISE.",
    "State 3, ambiguous value: more than one possible person, or timing described only as soon, with no confirmed assignment. Owner: Not stated / unclear and Deadline: Not stated / unclear are correct. Do not write Owner: Jordan or Sam, and do not turn soon into a date.",
    "Return REVISE only for a real error: a dropped positive name or day, an invented fact, or an empty Main Discussion Points section. A negated owner or deadline is not a dropped fact.",
    "A named owner stays even when the deadline sentence is negated.",
    "We agreed and the group decided are decisions.",
    "Judge the draft only against these notes.",
    "",
    "ORIGINAL MEETING NOTES:",
    originalNotes,
    "",
    "MEETING SUMMARY DRAFT:",
    draft,
  ]).join("\n");
  if (!message.includes(originalNotes)) {
    throw new Error("The reviewer message dropped the original meeting notes.");
  }
  return message;
}

